import React, { useCallback } from 'react';
import { Button, ColorPicker, IconButton, Input } from '@grafana/ui';
// One row per known business node type — label + color. Deliberately a
// small explicit list (not a hash-derived auto-color), since the real
// application's node types are a finite, known enum, unlike the arbitrary
// datasets used for learning Cypher.
export const NodeTypeColorEditor = ({ value, onChange }) => {
    const rows = value ?? [];
    const updateRow = useCallback((index, patch) => {
        const next = rows.slice();
        next[index] = { ...next[index], ...patch };
        onChange(next);
    }, [rows, onChange]);
    const removeRow = useCallback((index) => {
        onChange(rows.filter((_, i) => i !== index));
    }, [rows, onChange]);
    const addRow = useCallback(() => {
        onChange([...rows, { label: '', color: '#888888' }]);
    }, [rows, onChange]);
    return (React.createElement("div", null,
        rows.map((row, i) => (React.createElement("div", { key: i, style: { display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 } },
            React.createElement(ColorPicker, { color: row.color, onChange: (color) => updateRow(i, { color }) }),
            React.createElement(Input, { value: row.label, placeholder: "Node label, e.g. Desk", onChange: (e) => updateRow(i, { label: e.currentTarget.value }), width: 22 }),
            React.createElement(IconButton, { name: "trash-alt", "aria-label": "Remove", onClick: () => removeRow(i) })))),
        React.createElement(Button, { icon: "plus", size: "sm", variant: "secondary", onClick: addRow }, "Add node type")));
};
